arguments.command:
cat << 'EOF' > /app/output/template.html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Nine Decades of Oscar-Winning Scores</title>
    <style>
        :root {
            --bg-color: #fafafa;
            --text-primary: #111827;
            --text-secondary: #4b5563;
            --accent-gold: #b4975a;
            --accent-dark: #1f2937;
            --border-color: #e5e7eb;
            --card-bg: #ffffff;
        }
        body {
            font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
            background-color: var(--bg-color);
            color: var(--text-primary);
            line-height: 1.6;
            margin: 0;
            padding: 0;
        }
        .container {
            max-width: 1000px;
            margin: 0 auto;
            padding: 40px 20px;
        }
        header {
            text-align: center;
            margin-bottom: 50px;
            padding-bottom: 30px;
            border-bottom: 2px solid var(--accent-gold);
        }
        h1 {
            font-size: 2.5rem;
            color: var(--accent-dark);
            margin-bottom: 10px;
        }
        .subtitle {
            font-size: 1.2rem;
            color: var(--text-secondary);
        }
        h2 {
            font-size: 1.8rem;
            color: var(--accent-dark);
            margin-top: 40px;
            border-bottom: 1px solid var(--border-color);
            padding-bottom: 10px;
        }
        h3 {
            font-size: 1.4rem;
            color: var(--accent-dark);
            margin-top: 30px;
        }
        .kpi-container {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 20px;
            margin: 40px 0;
        }
        .kpi-card {
            background: var(--card-bg);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 20px;
            text-align: center;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
        }
        .kpi-value {
            font-size: 2.5rem;
            font-weight: bold;
            color: var(--accent-gold);
            margin: 10px 0;
        }
        .kpi-label {
            font-size: 0.9rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-secondary);
            font-weight: 600;
        }
        .chart-container {
            background: var(--card-bg);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 20px;
            margin: 30px 0;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
            position: relative;
            height: 400px;
            width: 100%;
        }
        table {
            width: 100%;
            border-collapse: collapse;
            margin: 30px 0;
            background: var(--card-bg);
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
            border-radius: 8px;
            overflow: hidden;
        }
        th, td {
            padding: 15px;
            text-align: left;
            border-bottom: 1px solid var(--border-color);
        }
        th {
            background-color: var(--accent-dark);
            color: white;
            font-weight: 600;
        }
        tr:last-child td {
            border-bottom: none;
        }
        .era-card {
            background: var(--card-bg);
            border-left: 4px solid var(--accent-gold);
            padding: 20px;
            margin: 20px 0;
            box-shadow: 0 4px 6px rgba(0, 0, 0, 0.05);
        }
        .era-title {
            font-weight: bold;
            font-size: 1.2rem;
            color: var(--accent-dark);
            margin-top: 0;
        }
        .milestone-list {
            list-style: none;
            padding: 0;
        }
        .milestone-item {
            background: var(--card-bg);
            padding: 15px;
            margin-bottom: 10px;
            border-radius: 6px;
            border: 1px solid var(--border-color);
            display: flex;
            align-items: flex-start;
        }
        .milestone-year {
            font-weight: bold;
            color: var(--accent-gold);
            min-width: 80px;
        }
        .milestone-content {
            flex-grow: 1;
        }
    </style>
    <!-- Include Chart.js -->
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
</head>
<body>
    <div class="container">
        <header>
            <h1>Nine Decades of Oscar-Winning Scores</h1>
            <div class="subtitle">A Historical Trend Analysis (1934–2026)</div>
        </header>

        <!-- KPI Section -->
        <section id="kpis">
            <div class="kpi-container">
                <div class="kpi-card">
                    <div class="kpi-label">Total Unique Composers</div>
                    <div class="kpi-value">{{ unique_composers }}</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Max Wins by a Composer</div>
                    <div class="kpi-value">{{ max_wins }}</div>
                    <div class="kpi-label" style="text-transform: none; margin-top: 5px;">({{ max_win_composers|join(', ') }})</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Repeat Winner Rate</div>
                    <div class="kpi-value">{{ "%.1f"|format(repeat_winner_rate) }}%</div>
                </div>
                <div class="kpi-card">
                    <div class="kpi-label">Most Unique Winners</div>
                    <div class="kpi-value">{{ best_decade }}s</div>
                </div>
            </div>
        </section>

        <!-- 1. Overview Section -->
        <section id="overview">
            <h2>Dataset Overview & Historical Context</h2>
            <p>This report analyzes the history of the Academy Award for Best Original Score across 93 continuous ceremonies from 1934 to 2026. The dataset encompasses a total of 93 awarded films and reflects the evolving musical tastes and scoring conventions of the Academy.</p>
            <p>During this period, a total of {{ unique_composers }} distinct composers have been honored, illustrating both the concentration of talent among a select few dominant figures and the diverse array of musicians who have contributed to cinema's highest musical honor.</p>
        </section>

        <!-- 2. Top Composers Section -->
        <section id="top-composers">
            <h2>Most Awarded Composers</h2>
            <p>The history of Oscar-winning scores is characterized by a mix of solitary triumphs and sustained dominance. A significant portion of the awards has been concentrated among a few highly prolific composers who have repeatedly captured the Academy's favor.</p>

            <div class="chart-container">
                <canvas id="topComposersChart"></canvas>
            </div>

            <table>
                <thead>
                    <tr>
                        <th>Composer</th>
                        <th>Wins</th>
                        <th>Winning Films</th>
                    </tr>
                </thead>
                <tbody>
                    {% for composer in top_composers %}
                    <tr>
                        <td><strong>{{ composer.name }}</strong></td>
                        <td>{{ composer.wins }}</td>
                        <td>{{ composer.films|join(', ') }}</td>
                    </tr>
                    {% endfor %}
                </tbody>
            </table>
        </section>

        <!-- 3. Temporal Patterns -->
        <section id="temporal-patterns">
            <h2>Temporal Patterns & Decade-by-Decade Breakdown</h2>
            <p>Analyzing the awards by decade reveals shifts in the Academy's preference for repeat winners versus new talent. The {{ best_decade }}s stands out as the most diverse decade, featuring the highest number of unique winning composers.</p>

            <div class="chart-container">
                <canvas id="decadeChart"></canvas>
            </div>
        </section>

        <!-- 4. Era-Based Analysis -->
        <section id="era-analysis">
            <h2>Era-Based Analysis of Winning Scores</h2>
            <p>The progression of winning scores can be categorized into four distinct historical eras, each defined by prevailing stylistic trends and leading composers.</p>

            {% for era in eras %}
            <div class="era-card">
                <h3 class="era-title">{{ era.name }}</h3>
                <p><strong>Total Ceremonies:</strong> {{ era.count }} | <strong>Unique Winners:</strong> {{ era.unique_winners }}</p>
                <p><strong>Defining Composers:</strong> {{ era.top_composers|join(', ') }}</p>
                <p><strong>Representative Films:</strong> {{ era.sample_films|join(', ') }}</p>
            </div>
            {% endfor %}
        </section>

        <!-- 5. Notable Milestones -->
        <section id="notable-milestones">
            <h2>Notable Milestones & Records</h2>
            <ul class="milestone-list">
                <li class="milestone-item">
                    <div class="milestone-year">1934</div>
                    <div class="milestone-content">
                        <strong>First Winner Recorded:</strong> Louis Silvers for <em>One Night of Love</em> at the inaugural ceremony recorded in this dataset.
                    </div>
                </li>
                {% if max_gap_milestone %}
                <li class="milestone-item">
                    <div class="milestone-year">{{ max_gap_milestone.year2 }}</div>
                    <div class="milestone-content">
                        <strong>Longest Gap Between Wins:</strong> {{ max_gap_milestone.composer }} waited {{ max_gap_milestone.gap }} years between wins ({{ max_gap_milestone.year1 }} to {{ max_gap_milestone.year2 }}).
                    </div>
                </li>
                {% endif %}
                <li class="milestone-item">
                    <div class="milestone-year">2026</div>
                    <div class="milestone-content">
                        <strong>Most Recent Winner:</strong> Ludwig Göransson for <em>Sinners</em>.
                    </div>
                </li>
            </ul>
        </section>

        <!-- 6. Conclusions -->
        <section id="conclusions">
            <h2>Key Takeaways & Forward-Looking Observations</h2>
            <ul>
                <li><strong>Concentration of Excellence:</strong> With {{ unique_composers }} unique composers over 93 ceremonies, the data indicates a strong tendency for the Academy to reward familiar, established talent, evidenced by a repeat winner rate of {{ "%.1f"|format(repeat_winner_rate) }}%.</li>
                <li><strong>Generational Shifts:</strong> The transition from the Golden Age's symphonic dominance (e.g., Steiner, Waxman) to the Contemporary era highlights a broadening of acceptable styles, though certain composers like {{ max_win_composers[0] }} transcend eras.</li>
                <li><strong>Recent Trends:</strong> The recent successes of composers like Ludwig Göransson suggest a modern inclination towards innovative, genre-blending soundscapes that define contemporary cinema.</li>
            </ul>
        </section>

        <footer style="margin-top: 50px; text-align: center; color: var(--text-secondary); font-size: 0.9rem;">
            Generated by Report Generator | Data Source: All Oscar Soundtracks (1934–2026)
        </footer>
    </div>

    <!-- Chart Configuration Scripts -->
    <script>
        // Top Composers Chart
        const topComposersCtx = document.getElementById('topComposersChart').getContext('2d');
        new Chart(topComposersCtx, {
            type: 'bar',
            data: {
                labels: {{ chart_top_composers_labels | tojson }},
                datasets: [{
                    label: 'Oscar Wins',
                    data: {{ chart_top_composers_data | tojson }},
                    backgroundColor: '#b4975a',
                    borderWidth: 1
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true,
                        ticks: { stepSize: 1 }
                    }
                },
                plugins: {
                    legend: { display: false }
                }
            }
        });

        // Decade Breakdown Chart
        const decadeCtx = document.getElementById('decadeChart').getContext('2d');
        new Chart(decadeCtx, {
            type: 'line',
            data: {
                labels: {{ chart_decades_labels | tojson }},
                datasets: [{
                    label: 'Unique Winners per Decade',
                    data: {{ chart_decades_unique | tojson }},
                    borderColor: '#1f2937',
                    backgroundColor: 'rgba(31, 41, 55, 0.1)',
                    borderWidth: 2,
                    fill: true,
                    tension: 0.3
                },
                {
                    label: 'Total Awards in Decade',
                    data: {{ chart_decades_total | tojson }},
                    borderColor: '#b4975a',
                    borderWidth: 2,
                    borderDash: [5, 5],
                    fill: false,
                    tension: 0.3
                }]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    y: {
                        beginAtZero: true,
                        ticks: { stepSize: 1 }
                    }
                }
            }
        });
    </script>
</body>
</html>
EOF
